<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class PayrollLine extends Model { use HasFactory; protected $fillable=['payroll_run_id','business_id','personnel_id','personnel_code_snapshot','personnel_name_snapshot','position_snapshot','hourly_basic_pay','ot_pay','commission_amount','guaranteed_top_up','gross_compensation','adjustments_total','cash_advance_deductions','payroll_recovery_deductions','statutory_programs_snapshot','sss_employee','sss_employer','philhealth_employee','philhealth_employer','pagibig_employee','pagibig_employer','statutory_employee_deductions','statutory_employer_contributions','net_pay','status']; protected function casts():array{return['hourly_basic_pay'=>'decimal:2','ot_pay'=>'decimal:2','commission_amount'=>'decimal:2','guaranteed_top_up'=>'decimal:2','gross_compensation'=>'decimal:2','adjustments_total'=>'decimal:2','cash_advance_deductions'=>'decimal:2','payroll_recovery_deductions'=>'decimal:2','statutory_programs_snapshot'=>'array','sss_employee'=>'decimal:2','sss_employer'=>'decimal:2','philhealth_employee'=>'decimal:2','philhealth_employer'=>'decimal:2','pagibig_employee'=>'decimal:2','pagibig_employer'=>'decimal:2','statutory_employee_deductions'=>'decimal:2','statutory_employer_contributions'=>'decimal:2','net_pay'=>'decimal:2'];} public function run():BelongsTo{return $this->belongsTo(PayrollRun::class,'payroll_run_id');} public function personnel():BelongsTo{return $this->belongsTo(Personnel::class);} public function cashAdvanceAllocations():HasMany{return $this->hasMany(PayrollCashAdvanceAllocation::class);} public function recoveryAllocations():HasMany{return $this->hasMany(PayrollRecoveryAllocation::class,'payroll_line_id')->orderBy('id');} }
